import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"晶圆装载与预对准","description":"","frontmatter":{"title":"晶圆装载与预对准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-load-prealign.md","filePath":"litho/wafer-load-prealign.md","lastUpdated":1789023840000}'),c={name:"litho/wafer-load-prealign.md"};function _(f,a,m,E,B,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="晶圆装载与预对准" tabindex="-1">晶圆装载与预对准 <a class="header-anchor" href="#晶圆装载与预对准" aria-label="Permalink to &quot;晶圆装载与预对准&quot;">​</a></h1><div class="epigraph"><p>机械手把片放到预对准器上找缺口，再交给夹盘。缺口误差几角分，精细对准就要用掉行程。</p><footer>—— 对照 scanner pre-alignment / notch finding 通识</footer></div><p><a href="/litho/thermal-airflow-control">上一课</a>维持柜内气候。缺口是进片：FOUP → 机械手 → 预对准 → 夹盘。本课钉装载与预对准，掩模库下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精细对准传感器视场有限。预对准太差，标记不进窗，这场报错或盲曝。夹盘吸偏、背面颗粒垫高，调平从一开始就歪。把对准失败全写成标记设计，会漏机械。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光学找 notch/flat，旋转到配方角度，再放夹盘。真空吸盘检查泄漏。颗粒：背面清洗课的后果在这里爆发。节拍：装载时间进产能死时间，与双台掩盖相关。</p>',7)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FOUP%5B%22FOUP%22%5D%20--%3E%20ROB%5B%22%E6%9C%BA%E6%A2%B0%E6%89%8B%22%5D%0A%20%20ROB%20--%3E%20PRE%5B%22%E7%BC%BA%E5%8F%A3%E9%A2%84%E5%AF%B9%E5%87%86%22%5D%0A%20%20PRE%20--%3E%20CHK%5B%22%E5%A4%B9%E7%9B%98%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20CHK%20--%3E%20ALN%5B%22%E7%B2%BE%E7%BB%86%E5%AF%B9%E5%87%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">薄片、翘曲片预对准更难。配方要有翘曲容忍，否则只服务理想硅。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缺口 locates 旋转零点。残余角误差 × 半径 = 边缘切向偏差，精细对准用网格吸收，但标记必须仍在捕获窗。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课掩模怎么上：另一只手、另一套夹持。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预对准把精细对准关进视场。</li><li>夹盘真空与背面颗粒是装载质量。</li><li>出处：对准传感器课；背面清洗课。</li></ul>',7))])}const T=l(c,[["render",_]]);export{P as __pageData,T as default};
